/* ===== Dados do sistema: vêm do banco compartilhado (Cloudflare D1) ===== */
var TODAY=new Date();TODAY.setHours(0,0,0,0);
var TD=ymd(TODAY);
var MES=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
var MES3=["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];
var DIA3=["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"];
var DIA_EXT=["domingo","segunda","terça","quarta","quinta","sexta","sábado"];
function rng(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;var t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function brl(v,dec){return "R$ "+v.toLocaleString("pt-BR",{minimumFractionDigits:dec===0?0:2,maximumFractionDigits:dec===0?0:2})}
function ymd(d){return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function dmy(s){var p=s.split("-");return p[2]+"/"+p[1]+"/"+p[0]}
function addDays(d,n){var x=new Date(d);x.setDate(x.getDate()+n);return x}
function diffDays(a,b){return Math.round((new Date(a)-new Date(b))/864e5)}

var SERV={
  "Dedetização":{c:"#253C8D",g:"Controle de pragas",sh:"Dedetização"},
  "Desratização":{c:"#253C8D",g:"Controle de pragas",sh:"Desratização"},
  "Termonebulização":{c:"#253C8D",g:"Controle de pragas",sh:"Termonebulização"},
  "Descupinização":{c:"#253C8D",g:"Controle de pragas",sh:"Descupinização"},
  "Limpeza dos reservatórios de água inferiores e superiores":{c:"#3872CF",g:"Reservatórios de água",sh:"Reservatórios inf. e sup."},
  "Limpeza dos reservatórios de água inferiores":{c:"#3872CF",g:"Reservatórios de água",sh:"Reservatórios inferiores"},
  "Limpeza dos reservatórios de água superiores":{c:"#3872CF",g:"Reservatórios de água",sh:"Reservatórios superiores"},
  "Limpeza preventiva da rede de esgoto":{c:"#B49B54",g:"Redes de esgoto e pluvial",sh:"Rede de esgoto"},
  "Limpeza preventiva da rede de água pluvial":{c:"#B49B54",g:"Redes de esgoto e pluvial",sh:"Rede pluvial"}
};
/* serviço fora da lista (ex.: trazido da agenda antiga) aparece em cinza */
function svCor(s){return SERV[s]?SERV[s].c:"#8A8F98"}
var SFAM=[["Controle de pragas","#253C8D"],["Reservatórios de água","#3872CF"],["Redes de esgoto e pluvial","#B49B54"]];
var LOGO="data:image/png;base64,";

/* ===== banco de dados compartilhado (Cloudflare D1) =====
   O servidor entrega os dados junto com a página (window.MF_BOOT). Cada alteração na tela é
   comparada com a última versão do banco e só o que mudou é enviado. A cada poucos segundos a
   tela pergunta ao servidor o que outras pessoas mudaram e se atualiza sozinha. */
var BOOT=window.MF_BOOT||{ver:0,dados:{},usuario:null};
var EU=BOOT.usuario||{nome:"",iniciais:"",papel:"leitura",email:""};
var DB_KEYS=["CLIENTES","FUNC","OSL","EMAILS","TAREFAS","EVENTS","RECEBER","VK"];
var SYNC={ver:BOOT.ver||0,snap:{},enviando:false,fila:false,ultimo:BOOT.ver!=null?new Date():null,erro:false,pend:0,render:false};
function dbKey(k,x){if(k==="OSL")return String(x[0]);if(k==="VK")return String(x);return x&&x.id!=null?String(x.id):JSON.stringify(x)}
function dbLoad(k){var a=(BOOT.dados&&BOOT.dados[k])||[],m={};a.forEach(function(x){m[dbKey(k,x)]=JSON.stringify(x)});SYNC.snap[k]=m;return a.slice()}
/* o que mudou na tela desde a última versão do banco */
function dbOps(){var ops=[];DB_KEYS.forEach(function(k){var arr=window[k],snap=SYNC.snap[k],vis={};if(!arr||!snap)return;
  arr.forEach(function(x){var key=dbKey(k,x);if(vis[key])return;vis[key]=1;var j=JSON.stringify(x);if(snap[key]!==j)ops.push({c:k,k:key,d:j,n:snap[key]===undefined?1:0})});
  Object.keys(snap).forEach(function(key){if(!vis[key])ops.push({c:k,k:key,d:null})})});return ops}
function api(met,url,body){return fetch(url,{method:met,credentials:"same-origin",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined}).then(function(r){
  if(r.status===401){location.href="/login";throw {status:401}}
  return r.json().catch(function(){return {}}).then(function(j){if(!r.ok){j.status=r.status;throw j}return j})})}
function dbSave(saindo){
  var ops=dbOps();SYNC.pend=ops.length;if(!ops.length){syncStatus();return}
  if(EU.papel==="leitura"){dbRevert();toast("Seu acesso é só para consulta: a alteração não foi salva.");return}
  if(saindo===true||(saindo&&saindo.type)){try{fetch("/api/sync",{method:"POST",keepalive:true,credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({ops:ops})})}catch(e){}return}
  if(SYNC.enviando){SYNC.fila=true;return}
  SYNC.enviando=true;syncStatus();
  api("POST","/api/sync",{ops:ops}).then(function(r){
    var rej={};(r.rejeitados||[]).forEach(function(x){rej[x.c+"\u0001"+x.k]=x.motivo});
    ops.forEach(function(o){if(rej[o.c+"\u0001"+o.k])return;if(o.d===null)delete SYNC.snap[o.c][o.k];else SYNC.snap[o.c][o.k]=o.d});
    SYNC.erro=false;SYNC.ultimo=new Date();
    if(r.rejeitados&&r.rejeitados.length)dbConflitos(r.rejeitados);
  }).catch(function(e){SYNC.erro=e&&e.status!==undefined?(e.erro||"Erro ao salvar."):"Sem conexão";
    if(e&&e.status===403){dbRevert();toast(e.erro||"Você não tem permissão para esta alteração.")}
  }).then(function(){SYNC.enviando=false;SYNC.pend=dbOps().length;syncStatus();if(SYNC.fila){SYNC.fila=false;dbSave()}});
}
/* volta a tela para a última versão do banco */
function dbRevert(){DB_KEYS.forEach(function(k){var arr=window[k],snap=SYNC.snap[k];arr.length=0;Object.keys(snap).forEach(function(key){arr.push(JSON.parse(snap[key]))});if(k==="OSL")arr.sort(function(a,b){return a[0]<b[0]?1:-1})});SYNC.pend=0;dbRefresh(true)}
/* outra pessoa gravou o mesmo número de OS (ou o mesmo aviso) ao mesmo tempo: o registro daqui ganha outro número */
function dbConflitos(rs){
  var guard=rs.map(function(x){var arr=window[x.c],i=arr.findIndex(function(y){return dbKey(x.c,y)===x.k});return i<0?null:{c:x.c,m:x.motivo,item:arr.splice(i,1)[0]}}).filter(Boolean);
  dbPoll(true).then(function(){guard.forEach(function(g){if(g.m==="aviso")return;
    if(g.c==="OSL"){var antigo=g.item[0];g.item[0]=nextOS();OSL.unshift(g.item);toast("A "+antigo+" foi registrada por outra pessoa. A sua virou "+g.item[0]+".")}
    else if(g.c==="EVENTS"){g.item.id=g.item.id+"-"+Math.floor(Math.random()*1e4);EVENTS.push(g.item)}
    else{g.item.id=nid(window[g.c]);window[g.c].push(g.item)}});dbRefresh(true);dbSave()});
}
/* aplica o que veio do servidor sem perder o que ainda não foi enviado daqui */
function dbApply(mud){var mudou=false;Object.keys(mud).forEach(function(k){var arr=window[k],snap=SYNC.snap[k];if(!arr||!snap)return;
  mud[k].forEach(function(p){var key=p[0],j=p[1],i=-1;for(var n=0;n<arr.length;n++)if(dbKey(k,arr[n])===key){i=n;break}
    var local=i>=0?JSON.stringify(arr[i]):undefined,sujo=local!==snap[key];
    if(j===null){delete snap[key];if(i>=0&&!sujo){arr.splice(i,1);mudou=true}return}
    snap[key]=j;if(sujo&&local!==undefined)return;if(local===j)return;
    var o=JSON.parse(j);
    if(i<0){if(k==="OSL")arr.unshift(o);else arr.push(o)}
    else if(Array.isArray(o)&&Array.isArray(arr[i])){arr[i].length=0;Array.prototype.push.apply(arr[i],o)}
    else if(o&&typeof o==="object"&&arr[i]&&typeof arr[i]==="object"){Object.keys(arr[i]).forEach(function(f){delete arr[i][f]});for(var f in o)arr[i][f]=o[f]}
    else arr[i]=o;
    mudou=true})});
  if(mudou)dbRefresh();return mudou}
function dbPoll(forcar){
  if(!forcar&&(SYNC.enviando||dbOps().length)){dbSave();return Promise.resolve()}
  return api("GET","/api/mudancas?desde="+SYNC.ver).then(function(r){if(r.mud)dbApply(r.mud);SYNC.ver=r.ver;SYNC.erro=false;SYNC.ultimo=new Date();syncStatus()})
    .catch(function(e){if(e&&e.status!==401){SYNC.erro="Sem conexão";syncStatus()}});
}
/* redesenha a tela aberta, a não ser que a pessoa esteja digitando ou com uma janela aberta */
function dbRefresh(ja){
  var ae=document.activeElement,ocupado=$$(".modal").some(function(m){return !m.hidden})||(ae&&ae!==document.body&&(/^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName)||ae.isContentEditable)&&!ae.closest(".top"));
  if(ocupado&&!ja){SYNC.render=true;return}
  SYNC.render=false;var on=$(".view.on");if(!on)return;var v=on.id.slice(2),y=window.scrollY;
  try{if(VIEWS[v]&&VIEWS[v].show)VIEWS[v].show();refreshSide();window.scrollTo(0,y)}catch(e){location.reload()}
}
function syncStatus(){var el=document.getElementById("syncSt");if(!el)return;
  var hr=SYNC.ultimo?SYNC.ultimo.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}):"";
  el.textContent=SYNC.erro?(SYNC.erro+(SYNC.pend?" · "+SYNC.pend+" alteração(ões) aguardando envio":"")+" · tentando de novo"):SYNC.enviando?"Salvando…":"Monte Fuji · banco compartilhado · atualizado às "+hr;
  el.classList.toggle("err",!!SYNC.erro)}
function dbDump(){var o={sistema:"Monte Fuji",versao:2,gerado:new Date().toISOString()};DB_KEYS.forEach(function(k){o[k]=window[k]});return o}
/* códigos únicos mesmo com várias pessoas cadastrando ao mesmo tempo */
function nid(a){var m=a.reduce(function(m,x){return Math.max(m,+x.id||0)},0);return Math.max(m+1,Date.now()*10+Math.floor(Math.random()*10))}

var CLIENTES=dbLoad("CLIENTES");
var FUNC=dbLoad("FUNC");
var OSL=dbLoad("OSL");      /* [número, data, cliente, serviço, técnico, valor, status] */
var EMAILS=dbLoad("EMAILS"); /* preenchido quando o Gmail for conectado */
var TAREFAS=dbLoad("TAREFAS");
var VK=dbLoad("VK");
var EVENTS=dbLoad("EVENTS");
var RECEBER=dbLoad("RECEBER");
var FATURAS=[];              /* Conta Azul, ainda não conectada */

var GAR_OPC=[[0,"Sem garantia"],[1,"1 mês"],[3,"3 meses"],[4,"4 meses"],[6,"6 meses"],[12,"12 meses"]];
function evOn(s){return EVENTS.filter(function(e){return e.date===s}).sort(function(a,b){return a.h-b.h})}

/* aniversários da equipe */
function bdaysOn(ds){var md=ds.slice(5);return FUNC.filter(function(f){return f.nasc&&f.nasc.slice(5)===md})}
function firstName(n){return n.split(" ")[0]}

/* histórico e garantias do cliente saem da agenda */
function cliEvs(c){return EVENTS.filter(function(e){return e.cli===c.nome})}
function histOf(c){return cliEvs(c).filter(function(e){return e.date<=TD}).sort(function(a,b){return a.date<b.date?1:-1}).map(function(e){return [e.date,(e.svs||[e.s])[0],(e.svs||[e.s]).join(", "),""]})}
function garOf(c){var seen={},out=[];cliEvs(c).filter(function(e){return e.gar>0}).forEach(function(e){var k=e.grp||e.id;if(seen[k])return;var g=e.grp?EVENTS.filter(function(x){return x.grp===e.grp}):[e];var last=g.map(function(x){return x.date}).sort().pop();if(last>TD)return;seen[k]=1;out.push([(e.svs||[e.s])[0],last,e.gar*30])});return out}

/* pastas do Drive conhecidas pelo sistema (as vinculadas aos clientes) */
var DRIVE_FOLDERS=CLIENTES.filter(function(c){return c.pasta}).map(function(c){return c.pasta.replace("Clientes / ","")});
function driveFiles(c){return osDoCliente(c).slice(0,6).map(function(o){return [o[0]+".pdf",o[1],"OS"]})}
function osDoCliente(c){return OSL.filter(function(o){return o[2]===c.nome}).sort(function(x,y){return x[1]<y[1]?1:-1})}
function nextOS(){var y=String(TODAY.getFullYear()),n=OSL.reduce(function(m,o){var p=String(o[0]).split("-");return p[1]===y?Math.max(m,+p[2]||0):m},0)+1;return "OS-"+y+"-"+String(n).padStart(4,"0")}
/* Conta Azul ainda não conectada: sem pagamentos */
function pagamentos(c){return []}

/* Receita Federal pela BrasilAPI (consulta real e gratuita) */
function consultaCNPJ(d,cb){
  fetch("https://brasilapi.com.br/api/cnpj/v1/"+d).then(function(r){if(!r.ok)throw new Error(r.status);return r.json()}).then(function(j){
    function cap(s){return String(s||"").toLowerCase().replace(/(^|\s)\S/g,function(m){return m.toUpperCase()}).replace(/ (D[aeo]s?|E) /g,function(m){return m.toLowerCase()})}
    var tel=String(j.ddd_telefone_1||"").replace(/\D/g,""),end=[cap(j.descricao_tipo_de_logradouro?j.descricao_tipo_de_logradouro+" "+j.logradouro:j.logradouro),j.numero].filter(Boolean).join(", ")+(j.complemento?" "+cap(j.complemento):"")+" · "+cap(j.bairro)+", "+cap(j.municipio)+"/"+(j.uf||"");
    cb(null,{razao:j.razao_social||"",fantasia:cap(j.nome_fantasia||j.razao_social||""),end:end,tel:tel.length>=10?"("+tel.slice(0,2)+") "+tel.slice(2,-4)+"-"+tel.slice(-4):"",email:String(j.email||"").toLowerCase(),perfil:/condom/i.test(j.razao_social||"")?"Condomínio":"Comércio",situacao:cap(j.descricao_situacao_cadastral||"—"),abertura:j.data_inicio_atividade||"",cnae:(j.cnae_fiscal?String(j.cnae_fiscal):"")+(j.cnae_fiscal_descricao?" · "+j.cnae_fiscal_descricao:"")});
  }).catch(function(e){cb(e)});
}
function fmtCNPJ(d){return d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,"$1.$2.$3/$4-$5")}

function recSt(r){if(r.pago)return["ok","Recebido"];if(!r.nf)return["ne","NF a emitir"];if(r.venc<TD)return["er","Vencido"];if(!r.cob)return["al","Cobrança pendente"];return["in","A vencer"]}

/* Vencimento de garantia: um item por agendamento com garantia, na data em que ela vence */
function vencList(){var g={};EVENTS.forEach(function(e){if(!e.gar)return;var k=e.grp||e.id;if(!g[k]||e.date>g[k].last)g[k]={k:k,cli:e.cli,svs:e.svs||[e.s],last:e.date,gar:e.gar,ev:e.id}});
  return Object.keys(g).map(function(k){var x=g[k];x.venc=addMonths(x.last,x.gar);
    x.renov=EVENTS.some(function(e){return e.cli===x.cli&&(e.grp||e.id)!==k&&e.date>x.last});return x}).filter(function(x){return !x.renov})}
function vencOn(k){return vencList().filter(function(x){return x.venc===k})}
/* Vencimentos do A receber, em verde na agenda */
function recOn(k){return RECEBER.filter(function(r){return r.venc===k})}
function recTit(r){return (r.pago?"Recebido: ":"A receber: ")+r.nome+" · "+brl(r.valor)}
function vencMsg(x){var c=CLIENTES.find(function(y){return y.nome===x.cli}),nm=c&&c.contato?firstName(c.contato):x.cli;
  return "Olá, "+nm+"! Tudo bem? Aqui é da Monte Fuji. O serviço de "+x.svs.join(", ").toLowerCase()+" realizado em "+dmy(x.last)+" está com a garantia vencendo em "+dmy(x.venc)+". Para manter o local protegido, precisamos agendar uma nova aplicação. Qual a melhor data para vocês?"}
/* Uma semana antes do vencimento cria a anotação de contato (uma vez só, mesmo se apagada) */
function syncVenc(){var n=0;vencList().forEach(function(x){if(VK.indexOf(x.k)>=0)return;var aviso=ymd(addDays(new Date(x.venc+"T12:00"),-7));
  if(TD<aviso||TD>ymd(addDays(new Date(x.venc+"T12:00"),30)))return;
  TAREFAS.push({id:nid(TAREFAS),col:"todo",t:"Garantia vencendo: "+x.cli,d:x.svs.join(", ")+" realizado em "+dmy(x.last)+". Vence em "+dmy(x.venc)+". Entrar em contato e agendar nova aplicação.",due:x.venc,who:"MF",done:false,vk:x.k,msg:vencMsg(x)});VK.push(x.k);n++});
  if(n)dbSave();return n}

/* Peças do comunicado (cabeçalho, mascote e rodapé), tiradas do modelo da Monte Fuji */
var COM_IMG={top:"data:image/jpeg;base64,",mid:"data:image/jpeg;base64,",masc:"data:image/png;base64,",bot:"data:image/jpeg;base64,"};
